  - cbn [sum_nat] in Hl. destruct (IH (skipn k bs) ltac:(rewrite skipn_length; lia)) as (W & B & SZ).
    assert (FL : forall j, (j <= k)%nat -> length (firstn j bs) = j) by (intros j Hj; rewrite firstn_length; lia).
    assert (GEN : forall c, cell_wf c -> cbytes c = firstn k bs -> csize c = k ->
              cells_wf (c :: tcells r (skipn k bs)) /\ cells_bytes (c :: tcells r (skipn k bs)) = bs /\ cells_size (c :: tcells r (skipn k bs)) = sum_nat (k :: r)).
    { intros c Hc Hb Hs. cbn [cells_wf cells_bytes cells_size sum_nat]. rewrite Hb, Hs, B, SZ, firstn_skipn. repeat split; try reflexivity. exact Hc. exact W. }
