    Proof.
      intros Lc mc moc hc j0 o1 o2 o3 o4 q1 q2 q3 q4 w1 w2 w3 pp1 p lenw len96 END1 END2 ap1
             ob h1 h2 h3 rawlen rawp tbt tbd tbl tbp ver verpad stg spd slen sq so1 so2 so3 ir1 ir2 ir3 ir4 sr1 sr2 sr3 sr4
             ij48 img ipad sj48 smg spad dates pr1 pr2 pr3 pr4 u1 u2 u3 u4 v1 v2 v3 v4 gtg gpd glen gq sigmd sigpk
             rawjunk
             x5 x6 x7 x15 x16 x17 x23 x28 x29 x30 x31
             B CH OW PERM HOB RP Hp1 Hp2 Hp2' Hp3 HA1 HA2 HPP1 RLpos.

      pose proof B as B0. binv_open B. pose proof (heap_mok _ _ HI _ _ _ _ HHc) as MK. pose proof LOSP as LOSP'. pose proof alloc_ceiling_pos as ACP.
      pose proof BCE as BCE'. pose proof CRB as CRB'. pose proof ALC as ALC'. pose proof B5 as B5'. pose proof B4 as B4'. pose proof DHI as DHI'.
      pose proof (unsigned_lit (bv_unsigned sp + -192) ltac:(lia)) as USP.
      flat constr:((raw_facts _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ OW HHc RP)) 5%nat. intros RBY RLEN RB2 ACB RIN.
      pose proof (bv_unsigned_in_range 64 so3) as R1. pose proof (bv_unsigned_in_range 64 w3) as R3. unfold bv_modulus in R1, R3. cbn in R1, R3.
      ch_open CH. unfold wbuf, SAVED in FR. cbn [app] in FR.
      splitat FR 9%nat PAR. splitat PAR 4%nat FR2.                 (* [comment removed for export] *)
      splitat K15 1%nat KPK. splitat KPK 1%nat KOPT. splitat KOPT 1%nat KNX.
      rewrite <- (Z_to_bv_bv_unsigned so3) in K3.
      flat constr:((bytes_at_slice mc rawp rawjunk ap1 (bv_unsigned so3) RBY ltac:(lia) ltac:(lia) ltac:(lia))) 2%nat. intros OBY OLEN.
      pose proof SIGALG as SPS. unfold x509_get_sig_alg_stmt, U_X509_GET_SIG_ALG in SPS.
      eapply aevtM_cut.
      { eapply SPS with (OID := CRT + 88) (OP := ap1) (OLEN := bv_unsigned so3) (PAR := bv_unsigned sp + -136) (MD := CRT + 720) (PK := CRT + 724) (OPTS := CRT + 728)
                        (BUF := rawp) (pp := pp1) (o0 := 0) (lo := lo) (bs := rawjunk) (h := hc) (LB := Lc ++ LB) (ptag := w1) (ppad := w2) (plen := w3)
                        (otg := so1) (opd := so2) (oxs := firstn (Z.to_nat (bv_unsigned so3)) (skipn (Z.to_nat (ap1 - rawp)) rawjunk)) (v1 := sigmd) (v2 := sigpk);
          try reflexivity; rewrite ?USP; try eassumption; try (unfold CRT_SIZE in *; plia);
          try (clear - SP16 SPR LOSP' CEIL ACP ALC'; Z.div_mod_to_equations; lia).
        all: try (rewrite RLEN; exact HPP1).
