      injection E0; clear E0; intros Emo Ems. subst ms' mo'x. rewrite ?USP in ST2. rewrite ?USP in HPX01. fix_ret 0x267c8. clear SPS.
      clear K15 KPK KOPT.
      assert (XD : forall A0 kk, (A0 + kk <= CRT + 720 \/ CRT + 736 <= A0) ->
                     disjoint_from [(CRT + 720, CRT + 720 + 4); (CRT + 724, CRT + 724 + 4); (CRT + 728, CRT + 728 + 8)] A0 kk)
        by (intros A0 kk Y1; cbn; lia).
      trX HPX01 XD. si_px HPX01.
      rewrite (Z_to_bv_bv_unsigned so3) in K3.
