      assert (HPX2 : heap_presx usegs L LB (bv_unsigned sp) X0 m m1).
      { eapply heap_presx_trans; [exact HPXc|]. eapply HPXdown; [exact HHc| exact HPX01|]. intros a Ha Ho. cbn [outside app] in Ho |- *. flat constr:(Ho) 2%nat. flclear Ho. intros Ho HoS. fp_out HoS. }
      pose proof (heap_presx_bytes_at usegs L _ _ _ _ _ _ _ HPX01 BYc ltac:(eapply client_range_block; [apply in_or_app; right; exact BIN| lia| lia]) ltac:(cbn; pose proof BCE; lia)) as BY2.
      (* [comment removed for export] *)
      assert (HX : exists Lc1, LB1 = Lc1 ++ (Lc ++ LB) /\ Permutation (Lc1 ++ Lc) (crt_blocks (f_of ob rawlen rawp 0 [] 0 [] 0 0 [] ext_own_zero o))
                               /\ (o = 0 \/ (In (o, 8) (Lc1 ++ Lc ++ LB) /\ 0 < o))).
      { destruct HLB as [[-> ->]|(_ & -> & Ho & _ & _)].
        - exists []. split; [reflexivity|]. split; [exact PERM| left; reflexivity].
        - exists [(o, 8)]. split; [reflexivity|]. split; [| right; split; [left; reflexivity| exact Ho]].
          rewrite crt_blocks_f_of. rewrite crt_blocks_f_of in PERM. unfold oblk at 1. unfold oblk in PERM at 1.
          rewrite Z.eqb_refl in PERM. destruct (Z.eqb_spec o 0); [lia|]. cbn [app] in PERM |- *. apply perm_skip. exact PERM. }
      flat constr:(HX) 4%nat. flclear HX. intros Lc1 -> PERM1 HSO.
      assert (OW2 : owns m1 (Lc1 ++ Lc ++ LB) CRT ob rawlen rawp 0 [] 0 [] 0 0 [] ext_own_zero o rawjunk).
      { assert (OWt : owns m1 (Lc1 ++ Lc ++ LB) CRT ob rawlen rawp 0 [] 0 [] 0 0 [] ext_own_zero 0 rawjunk).
        { unfold owns in OW |- *. eapply (crt_own_ok_presx2 usegs L PK mc m1 _ _ (Lc ++ LB));
            [exact OW| | | exact HPX01| eapply blocks_below_of_HEAP; exact HHc| | lia| exact MI2].
          - intros b Hb. apply in_or_app. right. apply in_or_app. left. eapply Permutation_in; [apply Permutation_sym; exact PERM| exact Hb].
          - intros b Hb. apply in_or_app. left. eapply Permutation_in; [apply Permutation_sym; exact PERM| exact Hb].
          - unfold fp_above. repeat constructor; cbn; unfold CRT_SIZE in *; lia. }
        unfold owns, crt_own_ok in OWt |- *. flat constr:(OWt) 10%nat. flclear OWt. intros C1 C2 C3 C4 C5 C6 _ C8 C9 _.
        cbn [f_of co_issuer_next co_issuer co_subject_next co_subject co_san_next co_san co_akid_next co_akid co_pol_next co_pol co_eku_next co_eku co_sigopts co_rawp co_rawlen co_pkinfo co_pkctx co_pkowned cj_raw jraw] in C1, C2, C3, C4, C5, C6, C8, C9 |- *.
        refine (conj C1 (conj C2 (conj C3 (conj C4 (conj C5 (conj C6 (conj HSO (conj C8 (conj C9 _))))))))).
        eapply (nodup_of_perm hc1 (Lc1 ++ Lc) LB m1 mo1); [rewrite <- app_assoc; exact HH2| exact PERM1]. }
      clear HHc HPXc HPX01 BYc OW MK STc MIc PERM SOc HLB. pose proof (heap_mok _ _ HI _ _ _ _ HH2) as MK.
      joinr FR PAR. joinr FR FR2.
      assert (BV2 : binv (Lc1 ++ Lc) m1 mo1 hc1 ([CB 8 j0] ++ wbuf o1 o2 o3 o4 ++ wbuf q1 q2 q3 q4 ++ wbuf w1 w2 w3 (Z_to_bv 64 pp1) ++ [C8 (Z_to_bv 64 p); C8 lenw; C8 len96])).
      { split; [rewrite <- app_assoc; exact HH2|]. split; [congruence|]. split; [eapply mo_frame_trans; eassumption|]. split; [exact HPX2|].
        split; [unfold wbuf, SAVED; cbn [app]; exact FR|]. split; [reflexivity|]. split; [exact BY2|]. split; [exact MI2|]. split; [exact SO2|]. split; [exact ST2| exact SIc]. }
      ch_close m1. rewrite app_assoc in OW2.
      zstep. if_cases KR; zify_cond KR.
      { (* [comment removed for export] *) kz KR. exit_with L_FB8 BV2 CH OW2 PERM1; [exact HOB| lia]. }
      kz KR. subst r.
      eapply S_ISSUER; [exact BV2| exact CH| exact OW2| exact PERM1| exact HOB| ..]; try assumption; try lia.
    Qed.
